create function pg_temp.publish_item(p_item uuid,p_asset uuid,p_hash text,p_order int,p_forged jsonb default '{"kind":"studio","rendererVersion":"untrusted"}')returns void language sql as $$
 insert into public.playlist_release_items(id,tenant_id,playlist_id,release_id,media_asset_id,media_variant_id,sort_order,duration_seconds,fit_mode,muted,asset_kind,asset_title,storage_path,mime_type,file_size_bytes,checksum_sha256,sites_studio_presentation_json)
 select p_item,'10000000-0000-4000-8000-000000191231','70000000-0000-4000-8000-000000191231','80000000-0000-4000-8000-000000191231',asset.id,variant.id,p_order,45,'contain',true,asset.kind,asset.title,variant.storage_path,variant.mime_type,variant.file_size_bytes,p_hash,p_forged from public.media_assets asset join public.media_variants variant on variant.tenant_id=asset.tenant_id and variant.asset_id=asset.id where asset.id=p_asset and asset.tenant_id='10000000-0000-4000-8000-000000191231' limit 1;
$$;
select ok(not has_function_privilege('authenticated','private.freeze_sites_studio_release_item_v1()','EXECUTE'),'browser cannot invoke the publication admission helper');
select lives_ok($$select pg_temp.publish_item('90000000-0000-4000-8000-000000191233','20000000-0000-4000-8000-000000191231',repeat('a',64),0)$$,'publishing freezes the actual verified Studio export');
select is((select sites_studio_presentation_json from public.playlist_release_items where id='90000000-0000-4000-8000-000000191233'),(select value->'sitesPresentation'from source_document),'supplied markup/document is ignored in favor of immutable export content');
select is((select jsonb_array_length(sites_studio_presentation_json#>'{slide,tv,rows}')from public.playlist_release_items where id='90000000-0000-4000-8000-000000191233'),17,'all canonical rows and all three pages are frozen');
update public.studio_project_drafts set document_json=jsonb_set(document_json,'{sitesPresentation,slide,title}','"Later draft title"') where project_id='30000000-0000-4000-8000-000000191231';
select is((select sites_studio_presentation_json#>>'{slide,title}'from public.playlist_release_items where id='90000000-0000-4000-8000-000000191233'),'Onze club','later draft edits do not mutate the published presentation');
select throws_ok($$select pg_temp.publish_item('90000000-0000-4000-8000-000000191234','20000000-0000-4000-8000-000000191231',repeat('f',64),1)$$,'23514','Studio export checksum does not match the release','changed export checksum fails before publication');
select lives_ok($$select pg_temp.publish_item('90000000-0000-4000-8000-000000191235','20000000-0000-4000-8000-000000191232',repeat('b',64),1)$$,'historical ordinary media can still publish');
select ok((select sites_studio_presentation_json is null from public.playlist_release_items where id='90000000-0000-4000-8000-000000191235'),'a caller cannot inject a Studio presentation into an ordinary photo');
select throws_ok($$update public.playlist_release_items set sites_studio_presentation_json=null where id='90000000-0000-4000-8000-000000191233'$$,'23514','playlist releases are immutable','the frozen presentation cannot be rewritten');
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000191231',true);
select is((select count(*)from public.playlist_release_items where tenant_id='10000000-0000-4000-8000-000000191232'),0::bigint,'tenant scope prevents cross-tenant release reads');
select throws_ok($$insert into public.playlist_release_items(tenant_id,playlist_id,release_id,media_asset_id,media_variant_id,sort_order,duration_seconds,fit_mode,muted,asset_kind,asset_title,storage_path,mime_type,file_size_bytes,checksum_sha256)values('10000000-0000-4000-8000-000000191231','70000000-0000-4000-8000-000000191231','80000000-0000-4000-8000-000000191231','20000000-0000-4000-8000-000000191231','90000000-0000-4000-8000-000000191231',2,45,'contain',true,'video','Direct write','tenants/10000000-0000-4000-8000-000000191231/assets/20000000-0000-4000-8000-000000191231/original/studio-output.mp4','video/mp4',1024,repeat('a',64))$$,'42501',null,'direct browser publication writes remain denied');
select *from finish();rollback;
